# flange: generated by ShapeBridge (https://github.com/gazi-faysal-jubayer/shapebridge)
# Units: mm. Edit the parameters below; geometry updates from them.

import adsk.core, adsk.fusion, traceback

FRAMES = {"XY": ((1, 0, 0), (0, 1, 0), (0, 0, 1)), "XZ": ((1, 0, 0), (0, 0, 1), (0, -1, 0)), "YZ": ((0, 1, 0), (0, 0, 1), (1, 0, 0))}


def run(context):
    ui = None
    try:
        app = adsk.core.Application.get()
        ui = app.userInterface
        design = adsk.fusion.Design.cast(app.activeProduct)
        design.designType = adsk.fusion.DesignTypes.ParametricDesignType
        up = design.userParameters
        root = design.rootComponent
        V = adsk.core.ValueInput.createByString
        P = adsk.core.Point3D.create
        ops = adsk.fusion.FeatureOperations
        Dir = adsk.fusion.ExtentDirections
        bases = {'XY': root.xYConstructionPlane, 'XZ': root.xZConstructionPlane, 'YZ': root.yZConstructionPlane}

        def param(name, expr, note):
            existing = up.itemByName(name)
            if existing:
                existing.expression = expr
            else:
                up.add(name, V(expr), "mm", note)

        def sketch_on(base, offset_expr):
            # Fusion's base planes may face the other way from ShapeBridge's; flip the offset to match
            n = FRAMES[base][2]
            fn = bases[base].geometry.normal
            sign = '' if fn.x * n[0] + fn.y * n[1] + fn.z * n[2] > 0 else '-'
            pi = root.constructionPlanes.createInput()
            pi.setByOffset(bases[base], V(sign + '(' + offset_expr + ')'))
            sk = root.sketches.add(root.constructionPlanes.add(pi))
            same = sk.xDirection.crossProduct(sk.yDirection).dotProduct(adsk.core.Vector3D.create(*n)) > 0
            return sk, same

        def to_sketch(sk, world):
            return sk.modelToSketchSpace(P(*world))

        def poly(sk, pts):
            lines = sk.sketchCurves.sketchLines
            ps = [to_sketch(sk, p) for p in pts]
            for i in range(len(ps)):
                lines.addByTwoPoints(ps[i], ps[(i + 1) % len(ps)])

        def pick_edges(body, sel):
            edges = adsk.core.ObjectCollection.create()
            box = body.boundingBox
            for e in body.edges:
                ok = sel == 'all'
                if sel == 'vertical':
                    g = e.geometry
                    ok = isinstance(g, adsk.core.Line3D) and abs(abs(g.startPoint.vectorTo(g.endPoint).z) - g.startPoint.distanceTo(g.endPoint)) < 1e-6
                elif sel in ('top', 'bottom'):
                    z = box.maxPoint.z if sel == 'top' else box.minPoint.z
                    ok = abs(e.boundingBox.minPoint.z - z) < 1e-3 and abs(e.boundingBox.maxPoint.z - z) < 1e-3
                if ok:
                    edges.add(e)
            return edges

        param("outer_d", "120 mm", "")
        param("bore_d", "40 mm", "")
        param("plate", "12 mm", "")
        param("hub_d", "60 mm", "")
        param("hub_h", "20 mm", "")
        param("bolt_circle", "45 mm", "")
        param("bolts", "6 mm", "")
        body = None

        # disc
        sk, same = sketch_on("XY", "0")
        sk.sketchCurves.sketchCircles.addByCenterRadius(to_sketch(sk, (0, 0, 0)), 6)
        inp = root.features.extrudeFeatures.createInput(sk.profiles.item(0), ops.NewBodyFeatureOperation if body is None else ops.JoinFeatureOperation)
        inp.setOneSideExtent(adsk.fusion.DistanceExtentDefinition.create(V("(abs(plate)) * 1 mm")), Dir.PositiveExtentDirection if same == (True) else Dir.NegativeExtentDirection)
        disc = root.features.extrudeFeatures.add(inp)
        body = body or root.bRepBodies.item(0)

        # hub
        sk, same = sketch_on("XY", "plate")
        sk.sketchCurves.sketchCircles.addByCenterRadius(to_sketch(sk, (0, 0, 1.2)), 3)
        inp = root.features.extrudeFeatures.createInput(sk.profiles.item(0), ops.NewBodyFeatureOperation if body is None else ops.JoinFeatureOperation)
        inp.setOneSideExtent(adsk.fusion.DistanceExtentDefinition.create(V("(abs(hub_h)) * 1 mm")), Dir.PositiveExtentDirection if same == (True) else Dir.NegativeExtentDirection)
        hub = root.features.extrudeFeatures.add(inp)
        body = body or root.bRepBodies.item(0)

        # bore
        sk, same = sketch_on("XY", "plate + hub_h")
        pts = adsk.core.ObjectCollection.create()
        pts.add(sk.sketchPoints.add(to_sketch(sk, (0, 0, 3.2))))
        inp = root.features.holeFeatures.createSimpleInput(V("(bore_d) * 1 mm"))
        inp.setPositionBySketchPoints(pts)
        inp.setDistanceExtent(V("(plate + hub_h) * 1 mm"))
        bore = root.features.holeFeatures.add(inp)
        body = body or root.bRepBodies.item(0)

        # bolt
        sk, same = sketch_on("XY", "plate")
        pts = adsk.core.ObjectCollection.create()
        pts.add(sk.sketchPoints.add(to_sketch(sk, (4.5, 0, 1.2))))
        inp = root.features.holeFeatures.createSimpleInput(V("(9) * 1 mm"))
        inp.setPositionBySketchPoints(pts)
        inp.setDistanceExtent(V("(plate) * 1 mm"))
        bolt = root.features.holeFeatures.add(inp)
        body = body or root.bRepBodies.item(0)

        # bolt_ring
        ents = adsk.core.ObjectCollection.create()
        ents.add(bolt)
        inp = root.features.circularPatternFeatures.createInput(ents, root.zConstructionAxis)
        inp.quantity = V("bolts")
        bolt_ring = root.features.circularPatternFeatures.add(inp)

        # edge
        inp = root.features.chamferFeatures.createInput2()
        inp.chamferEdgeSets.addEqualDistanceChamferEdgeSet(pick_edges(body, "top"), V("(1) * 1 mm"), True)
        edge = root.features.chamferFeatures.add(inp)

    except:
        if ui:
            ui.messageBox(traceback.format_exc())
